/**
 * The deployed Worker: the Next.js app as built by OpenNext, plus the daily
 * backup of the R2 data bucket (src/server/r2/backup.ts) on a Cron Trigger
 * (wrangler.jsonc → triggers). Backups land in the private xaa-backups bucket,
 * whose lifecycle rule deletes them after 35 days.
 */
// @ts-ignore — generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';
import { takeBackup, type BlobBucket } from './src/server/r2/backup';
import type { R2Like } from './src/server/r2/bucket';

interface Env {
  DATA?: unknown;
  BACKUPS?: unknown;
}

export default {
  fetch: handler.fetch,
  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.DATA || !env.BACKUPS) return;
    ctx.waitUntil(
      takeBackup(env.DATA as R2Like, env.BACKUPS as BlobBucket, 'daily').catch((err) => {
        console.error('daily backup failed:', err);
        throw err;
      }),
    );
  },
};

// @ts-ignore — the Durable Object classes OpenNext's caches may bind to
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
